(()=>{const reduced=matchMedia('(prefers-reduced-motion: reduce)');let navigating=false;addEventListener('pageshow',()=>{navigating=false;document.body.classList.remove('page-leaving');});if(!reduced.matches&&!document.documentElement.classList.contains('entrance-pending'))document.body.classList.add('page-entering');document.addEventListener('click',e=>{const a=e.target.closest('a[href]');if(!a||e.defaultPrevented||e.button!==0||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey||a.target||a.hasAttribute('download'))return;const u=new URL(a.href,location.href);if(u.origin!==location.origin||!/^https?:$/.test(u.protocol)||u.pathname===location.pathname||reduced.matches)return;if(navigating){e.preventDefault();return;}e.preventDefault();navigating=true;document.body.classList.add('page-leaving');setTimeout(()=>location.assign(u.href),160);});})();
